import re
from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class IpaddressParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('ipAddressAllocationMethod', 'DISCOVERED')
        self.set_uniqueIpAddressIdentifier()

    def set_uniqueIpAddressIdentifier(self):
        srch = re.search(r"TNL-(\d+)/IPNO-1/IPIF-(\d+)/", self.dist_name)
        tnl_num = srch.group(1)
        ipif_num = srch.group(2)

        if tnl_num == '1' or tnl_num == '4':
            self.set_parameter('uniqueIpAddressIdentifier', 'oam certman-server tracecontroller')

        elif (tnl_num == '2' or tnl_num == '5') and ipif_num == '1':
            self.set_parameter('uniqueIpAddressIdentifier', 'NG-C')
        elif (tnl_num == '2' or tnl_num == '5') and ipif_num == '2':
            self.set_parameter('uniqueIpAddressIdentifier', 'F1-C')
        elif (tnl_num == '2' or tnl_num == '5') and ipif_num == '3':
            self.set_parameter('uniqueIpAddressIdentifier', 'Xn-C')
        elif (tnl_num == '2' or tnl_num == '5') and ipif_num == '4':
            self.set_parameter('uniqueIpAddressIdentifier', 'X2-C')

        elif (tnl_num == '3' or tnl_num == '6') and ipif_num == '1':
            self.set_parameter('uniqueIpAddressIdentifier', 'NG-U')
        elif (tnl_num == '3' or tnl_num == '6') and ipif_num == '2':
            self.set_parameter('uniqueIpAddressIdentifier', 'F1-U Tracing')
        elif (tnl_num == '3' or tnl_num == '6') and ipif_num == '3':
            self.set_parameter('uniqueIpAddressIdentifier', 'Xn-U')
        elif (tnl_num == '3' or tnl_num == '6') and ipif_num == '4':
            self.set_parameter('uniqueIpAddressIdentifier', 'X2-U S1-U')

        self.set_tnl_conf(tnl_num, ipif_num)

    def set_tnl_conf(self, tnl_num, ipif_num):
        if self.enb_ent_config.get('tnl_conf'):
            interface_map = {'f1c': 'F1-C',
                             'ngc': 'NG-C',
                             'xnc': 'Xn-C',
                             'x2c': 'X2-C',
                             'f1u': 'F1-U Tracing',
                             'ngu': 'NG-U',
                             'xnu': 'Xn-U',
                             'x2u': 'X2-U',
                             's1u': 'S1-U'}
            param_value = ''
            dn_found = False
            for interface, dn in self.enb_ent_config.get('tnl_conf').items():
                custom_srch = re.search(r"TNL-(\d+)/IPNO-1/IPIF-(\d+)", dn)
                custom_tnl_num = custom_srch.group(1)
                custom_ipif_num = custom_srch.group(2)
                if custom_tnl_num == tnl_num and custom_ipif_num == ipif_num:
                    dn_found = True
                    param_value += ' ' + interface_map[interface]
            if dn_found:
                self.set_parameter('uniqueIpAddressIdentifier', param_value.strip())
